const char *link_path = "/tmp/link_file";
const char *attr_name = "user.description";
const char *value = "Direct link manipulation";
size_t len = strlen(value);

// Flag XATTR_REPLACE: Change attribute value if it exists.
// Returns 0 on success, -1 on error.
int status = lsetxattr(
    link_path,
    attr_name,
    value,
    len,
    XATTR_REPLACE
);

if (status == -1) {
    // Handle EPERM, ENOTSUP, etc.
}
